  pkcs1Encryption.push({ key: String(bits), message: hex(plain), ciphertext: hex(ciphertext), nodeDecrypted: hex(crypto.privateDecrypt({ key: objects[bits].privateKey, padding: C.RSA_PKCS1_PADDING }, ciphertext)) });
