    'random-2': pad(big(hex(crypto.randomBytes(k))) % N, k),
    'random-3': pad(big(hex(crypto.randomBytes(k))) % N, k),
    'random-4': pad(big(hex(crypto.randomBytes(k))) % N, k),
    'type-1-block': block(em(0, 1, Buffer.alloc(k - 3 - 4, 0xff), Buffer.from([0, 1, 2, 3, 4]))),
    'no-separator': block(em(0, 2, filler(k - 2), Buffer.alloc(0))),
    'short-padding': block(em(0, 2, filler(7), Buffer.concat([Buffer.from([0]), filler(k - 10)]))),
    'zero-right-after-type': block(em(0, 2, Buffer.alloc(0), Buffer.concat([Buffer.from([0]), filler(k - 3)]))),
    'nonzero-lead': block(em(1, 2, filler(k - 3 - 4), Buffer.from([0, 1, 2, 3, 4]))),
