const privateEncrypt = [];
for (const bits of [1024, 1025, 2048, 4096]) { const k = Math.ceil(bits / 8); for (const plain of [Buffer.alloc(0), message.subarray(0, 1), message.subarray(0, 32), crypto.randomBytes(k - 11)]) {
