  'publicDecrypt seven pad bytes': failure(() => crypto.publicDecrypt(k2048.publicKey, blockFor(2048, type1(0, 1, Buffer.alloc(7, 0xff), Buffer.concat([Buffer.from([0]), Buffer.alloc(246, 7)]))))),
  'publicDecrypt eight pad bytes': failure(() => crypto.publicDecrypt(k2048.publicKey, blockFor(2048, type1(0, 1, Buffer.alloc(8, 0xff), Buffer.concat([Buffer.from([0]), Buffer.alloc(245, 7)]))))),
