  'sign sha512 with 512-bit key': failure(() => crypto.sign('sha512', message, { key: objects[512].privateKey, padding: C.RSA_PKCS1_PADDING })),
  'sign sha384 with 512-bit key': failure(() => hex(crypto.sign('sha384', message, { key: objects[512].privateKey, padding: C.RSA_PKCS1_PADDING })).length),
