    const phi = (p - 1n) * (q - 1n); const lcm = phi / gcd(p - 1n, q - 1n);
    const pb = p.toString(2); const qb = q.toString(2);
    if (p > q) s.pGreaterThanQ++; if (d < lcm) s.dBelowLcm++; if (d * e % lcm === 1n) s.dTimesEIsOneModLcm++; if (d * e % phi === 1n) s.dIsInverseModPhi++;
