process.stdout.write(JSON.stringify({ node: { version: process.version, openssl: process.versions.openssl }, recorder: fs.readFileSync(__filename, 'utf8'), message: hex(message), keys, pkcs1, pss, pssKeyExportRefused, oaep, pkcs1Encryption, implicitRejection, privateEncrypt, raw, nodeBehaviour, keyGeneration }, null, 1) + '\n');
